def squeeze(s: str) -> str:
    """Map a short lowercase token to a shorter lowercase token (used for log keys)."""
    if not s:
        return ""
    n = 0
    for char in s:
        n = n * 26 + (ord(char) - ord('a'))

    if n < 26:
        return chr(ord('a') + n)
    else:
        return chr(ord('a') + n // 26) + chr(ord('a') + n % 26)
```

